-- 07_own_word_list.sql
-- Replaces the 5,000-word frequency list (found online) with our own list of 5,000 common words,
-- each with an English meaning and an example sentence written for this app (source = 'core').
--
-- What it does:
--   1. Makes a backup of vocabulary_bank and word_themes (…_backup_2026_10_18).
--   2. Loads the new words into a work table (5 blocks of 1,000 words).
--   3. Adds them to vocabulary_bank with Rank 1–5000, moves every topic link from an old
--      frequency word to the new word with the same spelling, then deletes the old frequency rows.
--      If a topic word would be lost, it stops and changes nothing.
--   4. Drops the work table and shows the counts.
-- Cheat sheet words (source 'cheatsheet') and C1–C2 words (source 'advanced') are not touched.
-- Run the whole file, or block by block from the top. Safe to run more than once.
-- 07_undo_own_word_list.sql puts the old list back.

-- 1. Backups (only made the first time)
do $$ begin
  if to_regclass('"French-schema".vocabulary_bank_backup_2026_10_18') is null then
    create table "French-schema".vocabulary_bank_backup_2026_10_18 as select * from "French-schema".vocabulary_bank;
    create table "French-schema".word_themes_backup_2026_10_18 as select * from "French-schema".word_themes;
  end if;
end $$;

-- 2. The new words, in 5 blocks of 1,000. Each block makes the work table itself if it is not there yet.

-- 2.1  words 1–1000
do $$ begin
create table if not exists "French-schema".core_words_import (
  n int primary key, french text not null, pos text, article text, gender text,
  english text, ex_fr text, ex_en text);
on conflict (n) do nothing;
end $$;

-- 2.2  words 1001–2000
do $$ begin
create table if not exists "French-schema".core_words_import (
  n int primary key, french text not null, pos text, article text, gender text,
  english text, ex_fr text, ex_en text);
on conflict (n) do nothing;
end $$;

-- 2.3  words 2001–3000
do $$ begin
create table if not exists "French-schema".core_words_import (
  n int primary key, french text not null, pos text, article text, gender text,
  english text, ex_fr text, ex_en text);
on conflict (n) do nothing;
end $$;

-- 2.4  words 3001–4000
do $$ begin
create table if not exists "French-schema".core_words_import (
  n int primary key, french text not null, pos text, article text, gender text,
  english text, ex_fr text, ex_en text);
on conflict (n) do nothing;
end $$;

-- 2.5  words 4001–5000
do $$ begin
create table if not exists "French-schema".core_words_import (
  n int primary key, french text not null, pos text, article text, gender text,
  english text, ex_fr text, ex_en text);
on conflict (n) do nothing;
end $$;

-- 3. Swap the lists
do $$
declare lost int;
begin
  create table if not exists "French-schema".core_words_import (
  n int primary key, french text not null, pos text, article text, gender text,
  english text, ex_fr text, ex_en text);
  if (select count(*) from "French-schema".core_words_import) <> 5000 then
    raise exception 'The work table should have 5000 words. Run all the blocks in part 2 first.';
  end if;

  -- 3a. add the new words (only once). Rank is set at the end.
  if not exists (select 1 from "French-schema".vocabulary_bank where source = 'core') then
    overriding system value
    select (select coalesce(max(id), 0) from "French-schema".vocabulary_bank) + c.n,
           c.french, c.pos, c.article, c.gender, c.english, c.ex_fr, c.ex_en,
           (select o.pron_guide from "French-schema".vocabulary_bank o
             where o.source = 'frequency' and o."French" = c.french and o.pron_guide is not null limit 1),
           'core'
    from "French-schema".core_words_import c
    order by c.n;
  end if;

  -- 3b. move topic links from old frequency words to the new words (same spelling, same kind of word if possible)
  select wt.theme_id, m.core_id, wt.sort_order
  from "French-schema".word_themes wt
  join "French-schema".vocabulary_bank o on o.id = wt.word_id and o.source = 'frequency'
  cross join lateral (
    select k.id as core_id
    from "French-schema".vocabulary_bank k
    where k.source = 'core' and lower(k."French") = lower(o."French")
    order by (case when o."Part_of_Speech" ~ '(^|,)\s*v' then 'v' when o."Part_of_Speech" ~ '(^|,)\s*n' then 'n'
                   when o."Part_of_Speech" ~ '(^|,)\s*adj' then 'adj' else o."Part_of_Speech" end)
             = (case when k."Part_of_Speech" = 'v' then 'v' when k."Part_of_Speech" ~ '^n' then 'n' else k."Part_of_Speech" end) desc,
             k.id
    limit 1
  ) m
  on conflict do nothing;

  -- 3c. stop if any topic word has no new match (nothing is changed in that case)
  select count(*) into lost
  from "French-schema".word_themes wt
  join "French-schema".vocabulary_bank o on o.id = wt.word_id and o.source = 'frequency'
  where not exists (select 1 from "French-schema".vocabulary_bank k where k.source = 'core' and lower(k."French") = lower(o."French"));
  if lost > 0 then
    raise exception '% topic words have no match in the new list. Nothing was changed.', lost;
  end if;

  -- 3d. delete the old list (its topic links go with it) and number the new one
  delete from "French-schema".vocabulary_bank where source = 'frequency';
  update "French-schema".vocabulary_bank v set "Rank" = v.id - (select min(id) - 1 from "French-schema".vocabulary_bank where source = 'core')
  where v.source = 'core';
end $$;

-- keep the id counter (if there is one) after the highest id
do $$
declare seq text := pg_get_serial_sequence('"French-schema".vocabulary_bank', 'id');
begin
  if seq is not null then
    perform setval(seq, (select max(id) from "French-schema".vocabulary_bank));
  end if;
end $$;

-- 4. Tidy up and check
drop table if exists "French-schema".core_words_import;

select (select count(*) from "French-schema".vocabulary_bank where source = 'core') as core_words,
       (select count(*) from "French-schema".vocabulary_bank where source = 'frequency') as old_frequency_words,
       (select count(*) from "French-schema".word_themes) as topic_links,
       (select min("Rank") || '–' || max("Rank") from "French-schema".vocabulary_bank where source = 'core') as ranks;
